var i=`1086-tortang-talong`;var o=`world-1086`;var t=`PH`;var a=`southeast-asia`;var l=4;var r=49;var s={en:`Tortang Talong`,ua:`Тортанг талонг`};var g={en:`Tortang Talong is a dish from Philippines prepared with eggplant, yellow onion, garlic, chicken egg. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Тортанг талонг, страва кухні країни Філіппіни, яку готують із таких продуктів: баклажан, жовта цибуля, часник, куряче яйце. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Roast in a preheated 190°C oven for about 25 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 25 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:25,i:[[`eggplant`,650,`g`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:7,i:[[`yellow-onion`,130,`g`],[`garlic`,2,`clove`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`chicken-egg`,4,`pcs`],[`table-salt`,6,`g`],[`ground-black-pepper`,3,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`canola-oil`,55,`ml`]]}];var u={slug:i,id:o,country:`PH`,region:a,servings:4,minutes:49,title:s,text:g,steps:d};export{t as country,u as default,o as id,r as minutes,a as region,l as servings,i as slug,d as steps,g as text,s as title};